use super::*;
use semio_s_artifact_stdio_contract::part21::{Part21Header,Part21Instance,Part21Value,Part21Decimal};
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::*};
#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_ifc2x3_all_four_actual_declaration_routes_preserve_decimals_and_warnings(){
    use semio_framework_os_kernel::io::{ArtifactDialect,io_mechanism::{io_export_sqlite_snapshot,io_import_sqlite_snapshot}};
    semio_framework_plugin::Plugin::<semio_framework_plugin::app::NoPluginApp>::builder("stdio").label("IFC SQLite declaration").version("0.0.1").package_id("semio:stdio").artifact(crate::declaration(crate::definition().unwrap()).unwrap()).try_build().unwrap();
    for subset in ["*","cv20","sav","cobie"]{let mut snapshot=fixture();if subset=="sav"{snapshot.document.instances.push(Part21Instance{id:42,entities:vec![("IFCSTRUCTURALANALYSISMODEL".into(),vec![])]});}let database=project(&snapshot);let dialect=ArtifactDialect{artifact_kind:"s.stdio.ifc".into(),standard:"2x3".into(),subset:subset.into()};let expected=snapshot.validate_sqlite_snapshot_subset(&dialect,&database,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().diagnostics;for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let mut phases=Vec::new();let exported=io_export_sqlite_snapshot(&dialect,&snapshot,encoding,SqliteDatabaseLimits::default(),&mut |p|{phases.push(p.phase);true}).await.unwrap();assert_eq!(exported.diagnostics,expected);let imported=io_import_sqlite_snapshot::<Ifc2x3Snapshot>(&dialect,&exported.value,SqliteDatabaseLimits::default(),&mut |p|{phases.push(p.phase);true}).await.unwrap();assert_eq!(imported.value,snapshot);assert_eq!(imported.diagnostics,expected);assert!(!phases.iter().any(|phase|matches!(phase,SqliteSnapshotPhase::EncodeNative|SqliteSnapshotPhase::DecodeNative)));}}
}
#[test]
fn sqlite_snapshot_ifc2x3_native_decimal_expansion_preflight_and_erased_encodings(){
    let snapshot=fixture();let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.stdio.ifc".into(),standard:"2x3".into(),subset:"*".into()};let provider=<Ifc2x3Snapshot as ArtifactSqliteSnapshot>::sqlite_codec();let db=project(&snapshot);let mut phases=Vec::new();assert!((provider.import)(&snapshot.schema,&dialect,db.clone(),SnapshotEncoding::Text,&mut SqliteSnapshotControl::new(&mut |p|{phases.push(p.phase);true},SqliteDatabaseLimits::default())).is_err());assert!(phases.contains(&SqliteSnapshotPhase::EncodeNative));let binary=(provider.import)(&snapshot.schema,&dialect,db,SnapshotEncoding::Binary,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(binary,store::os_io::IoPayload::Binary(<Ifc2x3Snapshot as store::ArtifactPack>::encode_pack(&snapshot)));
    let mut finite=fixture();finite.document.instances[0].entities[0].1=vec![Part21Value::Real(Part21Decimal{negative:true,coefficient:"00125".into(),scale:2,exponent:Some(0)}),Part21Value::Ref(u64::MAX)];for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(<Ifc2x3Snapshot as store::ArtifactPack>::encode_pack(&finite)),SnapshotEncoding::Text=>store::os_io::IoPayload::Text(<Ifc2x3Snapshot as store::ArtifactDsl>::print_dsl(&finite))};let database=(provider.export)(&finite.schema,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;let restored=(provider.import)(&finite.schema,&dialect,database,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(restored,payload);}
    assert!(snapshot.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Binary,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());assert!(snapshot.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Binary,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:1024,..SqliteDatabaseLimits::default()})).is_err());
}
#[test]
fn sqlite_snapshot_ifc2x3_exact_owned_mvd_diagnostics_and_coordinates(){let mut snapshot=fixture();snapshot.document.instances.push(Part21Instance{id:42,entities:vec![("IFCSTRUCTURALANALYSISMODEL".into(),vec![])]});let database=project(&snapshot);for(subset,expected)in [("cv20",crate::standards::v2x3::subsets::cv20::schema::check_cv20_conformance(&snapshot)),("sav",crate::standards::v2x3::subsets::sav::schema::check_sav_conformance(&snapshot)),("cobie",crate::standards::v2x3::subsets::cobie::schema::check_cobie_conformance(&snapshot))]{let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.stdio.ifc".into(),standard:"2x3".into(),subset:subset.into()};let actual=snapshot.validate_sqlite_snapshot_subset(&dialect,&database,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();assert_eq!(actual.diagnostics,expected);}for dialect in [store::os_io::ArtifactDialect{artifact_kind:"s.stdio.step".into(),standard:"2x3".into(),subset:"*".into()},store::os_io::ArtifactDialect{artifact_kind:"s.stdio.ifc".into(),standard:"4".into(),subset:"*".into()},store::os_io::ArtifactDialect{artifact_kind:"s.stdio.ifc".into(),standard:"2x3".into(),subset:"unknown".into()}]{assert!(snapshot.validate_sqlite_snapshot_subset(&dialect,&database,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err());}}
#[test]
fn sqlite_snapshot_ifc2x3_owned_view_preflight_budgets_and_cancellation(){
    let mut snapshot=fixture();snapshot.document.header.file_description=vec![Part21Value::List(vec![Part21Value::Str(format!("{}CoordinationView","文".repeat(40000)))])];let limits=SqliteDatabaseLimits{max_value_bytes:4096,..SqliteDatabaseLimits::default()};assert!(crate::standards::v2x3::subsets::cv20::schema::check_cv20_conformance_controlled(&snapshot,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());let mut reached=false;let mut callback=|p:SqliteSnapshotProgress|{if p.total>=100000{reached=true;false}else{true}};assert!(crate::standards::v2x3::subsets::cv20::schema::check_cv20_conformance_controlled(&snapshot,&mut SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default())).is_err());assert!(reached);
    snapshot.document.header.file_description=vec![Part21Value::List(vec![Part21Value::Str("CoordinationView StructuralAnalysisView FMHandOverView".into())])];for index in 0..300{snapshot.document.instances.push(Part21Instance{id:100+index,entities:vec![("IFCSPACE".into(),vec![])]});}let database=project(&snapshot);let mut checkpoints=0;let mut callback=|p:SqliteSnapshotProgress|{if p.completed>=256{checkpoints+=1;false}else{true}};let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.stdio.ifc".into(),standard:"2x3".into(),subset:"cobie".into()};assert!(snapshot.validate_sqlite_snapshot_subset(&dialect,&database,&mut SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default())).is_err());assert!(checkpoints>0);
}
#[test]
fn sqlite_snapshot_ifc2x3_refuses_corrupt_decimal_optional_owner_forests_and_limits(){let original=project(&fixture());for mutation in 0..8{let mut db=original.clone();match mutation{0=>db.table_mut("ifc2x3_entity_argument").unwrap().rows[0].values[3]=SqliteValue::Integer(999),1=>db.table_mut("ifc2x3_value").unwrap().rows.iter_mut().find(|row|row.text(1).unwrap()=="ref").unwrap().values[9]=SqliteValue::Text("00".into()),2=>db.table_mut("ifc2x3_instance").unwrap().rows[1].values[3]=SqliteValue::Text("0".into()),3=>db.table_mut("ifc2x3_document").unwrap().rows[0].values[3]=SqliteValue::Null,4=>db.table_mut("ifc2x3_file_name_argument").unwrap().rows[0].values[2]=SqliteValue::Integer(1),5=>db.table_mut("ifc2x3_value").unwrap().rows.iter_mut().find(|row|row.text(1).unwrap()=="real").unwrap().values[5]=SqliteValue::Integer(4294967296),6=>db.table_mut("ifc2x3_value").unwrap().rows.iter_mut().find(|row|row.text(1).unwrap()=="real").unwrap().values[6]=SqliteValue::Integer(2147483648),_=>db.table_mut("ifc2x3_value").unwrap().rows.iter_mut().find(|row|row.text(1).unwrap()=="real").unwrap().values[4]=SqliteValue::Text("1x".into())}assert!(restore(&db).is_err());}let limits=SqliteDatabaseLimits{max_value_bytes:1,..SqliteDatabaseLimits::default()};assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(Ifc2x3Snapshot::from_sqlite_database(&original,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());}
fn fixture()->Ifc2x3Snapshot{let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let mut args=vec![Part21Value::Unset,Part21Value::Derived,Part21Value::Int(i64::MIN),Part21Value::Int(i64::MAX)];for decimal in f["decimals"].as_array().unwrap(){args.push(Part21Value::Real(Part21Decimal{negative:decimal["negative"].as_bool().unwrap(),coefficient:decimal["coefficient"].as_str().unwrap().into(),scale:decimal["scale"].as_u64().unwrap()as u32,exponent:decimal["exponent"].as_i64().map(|n|n as i32)}));}args.extend([Part21Value::Str(f["text"].as_str().unwrap().into()),Part21Value::Enum("UNKNOWN".into()),Part21Value::Ref(u64::MAX),Part21Value::List(vec![]),Part21Value::Typed{name:"IFCLENGTHMEASURE".into(),items:vec![Part21Value::Int(1),Part21Value::List(vec![Part21Value::Derived])] }]);let edm=&f["edmPreamble"];let text=|key:&str|edm[key].as_str().unwrap().into();Ifc2x3Snapshot{schema:f["schema"].as_str().unwrap().into(),document:Part21Document{header:Part21Header{file_description:vec![Part21Value::List(vec![Part21Value::Str("ViewDefinition [CoordinationView, StructuralAnalysisView, FMHandOverView]".into())]),Part21Value::Typed{name:"HEADER_CUSTOM".into(),items:vec![]}],file_name:vec![Part21Value::Ref(0)],file_schema:vec![Part21Value::List(vec![Part21Value::Str("IFC2X3".into()),Part21Value::Str("IFC2X3".into())])]},instances:vec![Part21Instance{id:0,entities:vec![("IFCWALL".into(),args),("IFCROOT".into(),vec![Part21Value::Ref(0)])]},Part21Instance{id:u64::MAX,entities:vec![("TARGET".into(),vec![Part21Value::Ref(0)])]}]},edm_preamble:Some(Ifc2x3EdmPreamble{producer:text("producer"),module:text("module"),creation_date:text("creationDate"),host:text("host"),database:text("database"),database_version:text("databaseVersion"),database_creation_date:text("databaseCreationDate"),schema:text("schema"),model:text("model"),model_creation_date:text("modelCreationDate"),header_model:text("headerModel"),header_model_creation_date:text("headerModelCreationDate"),user:text("user"),group:text("group"),license:text("license"),options:text("options")})}}
fn project(snapshot:&Ifc2x3Snapshot)->SqliteDatabase{snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn restore(database:&SqliteDatabase)->Result<Ifc2x3Snapshot,String>{Ifc2x3Snapshot::from_sqlite_database(database,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()))}
#[test]
fn sqlite_snapshot_ifc2x3_exact_decimal_components_optional_edm_and_header_graph(){let snapshot=fixture();let db=project(&snapshot);let bytes=export_sqlite_database(&db,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();assert_eq!(restore(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap(),snapshot);assert_eq!(restore(&project(&Ifc2x3Snapshot::default())).unwrap(),Ifc2x3Snapshot::default());let mut absent=fixture();absent.edm_preamble=None;assert_eq!(restore(&project(&absent)).unwrap(),absent);}
#[test]
fn sqlite_snapshot_ifc2x3_independent_sqlite_decimal_and_edm_field_edit(){use std::io::Write;use std::process::{Command,Stdio};let bytes=export_sqlite_database(&project(&fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');if(db.query('SELECT kind FROM ifc2x3_value GROUP BY kind').all().length!==9||db.query('SELECT decimal_scale FROM ifc2x3_value WHERE decimal_scale=4294967295').get().decimal_scale!==4294967295)throw Error('decimal');const{importSqliteDatabase,exportSqliteDatabase}=await import('@semio-tech/framework');const{ifc2x3SnapshotFromSqliteDatabase,ifc2x3SnapshotToSqliteDatabase}=await import('@semio-tech/stdio-ifc');const other=Database.deserialize(await exportSqliteDatabase(await ifc2x3SnapshotToSqliteDatabase(await ifc2x3SnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize())))));const canonical=value=>JSON.stringify(value,(_,v)=>typeof v==='bigint'?v.toString():v);for(const table of['ifc2x3_document','ifc2x3_header','ifc2x3_file_description_argument','ifc2x3_file_name_argument','ifc2x3_file_schema_argument','ifc2x3_instance','ifc2x3_entity_type','ifc2x3_entity_argument','ifc2x3_value','ifc2x3_list_element','ifc2x3_typed_argument','ifc2x3_edm_preamble'])if(canonical(db.query('SELECT * FROM '+table+' ORDER BY id').safeIntegers(true).all())!==canonical(other.query('SELECT * FROM '+table+' ORDER BY id').safeIntegers(true).all()))throw Error('Rust/TypeScript IFC2x3 field mismatch '+table);other.close();db.query(\"UPDATE ifc2x3_edm_preamble SET options='SQL_EDIT'\").run();await Bun.write(Bun.stdout,db.serialize());db.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let out=child.wait_with_output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));assert_eq!(restore(&import_sqlite_database(&out.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap().edm_preamble.unwrap().options,"SQL_EDIT");}
